import { Hono } from "hono";
import { plan } from "./planner";

const app = new Hono();
app.get("/plan", (c) => {
  const from = c.req.query("from") ?? "";
  const to = c.req.query("to") ?? "";
  return c.json(plan({ from, to }));
});
export default app;

