import { db } from "./db";
import { fareFor } from "./fares";

/** Breadth-first search over stops: the route with the fewest transfers wins. */
export function plan({ from, to }: { from: string; to: string }) {
  const routes = db.query("select code, stops from routes").all();
  const best = fewestTransfers(routes, from, to);
  return { legs: best, fare: fareFor(best) };
}

